export const GROUPS = {
  'Health Science': ['Behavioral Health','Biomedical Equipment Technician','Dental Terminology','Health Informatics','Healthcare Administration','Human Growth & Development','Medical Law & Ethics','Medical Math','Medical Reading','Medical Spelling','Medical Terminology','Nutrition','Pathophysiology','Pharmacology','World Health & Disparities'],
  'Health Professions': ['Biotechnology','Clinical Lab Science (Medical Lab Scientist)','Clinical Nursing','Clinical Specialty','Dental Science','Family Medicine Physician','Home Health Aide','Genetics','Medical Assisting','Nursing Assisting','Occupational Therapy','Patient Care Technician','Personal Care','Pharmacy Science','Phlebotomy','Physical Therapy','Physician Assistant - Medical Case Challenge','Respiratory Therapy','Sports Medicine','Surgical Technologist','Veterinary Science'],
  'Emergency Preparedness': ['CERT Skills','CPR/First Aid','Emergency Medical Technician','Epidemiology','Life Support Skills','Mental Health Promotion','MRC Partnership','Public Health'],
  'Leadership': ['Extemporaneous Writing - Health Policy','Health Career Photography','Healthy Living','Interviewing Skills','Job Seeking Skills','Organizational Leadership','Prepared Speaking','Researched Persuasive Writing & Speaking','Speaking Skills'],
  'Teamwork': ['Biomedical Debate','Community Awareness','Creative Problem Solving','Forensic Science','Health Career Display','Health Education','HOSA Bowl','Medical Innovation','Parliamentary Procedure','Public Service Announcement','Research Poster']
};
export const EVENTS = Object.entries(GROUPS).flatMap(([category,names])=>names.map(name=>({name,category,special:['Personal Care','Life Support Skills','Interviewing Skills','Speaking Skills'].includes(name)})));
export const RANKS = ['Iron','Bronze','Silver','Gold','Platinum','Diamond','Ascendant','Immortal','Radiant'];
export const SCHOOLS = {westbridge:'Westbridge High',northview:'Northview High'};
export function seed() { return {version:1,school:'westbridge',role:'student',event:'Nursing Assisting',completed:[],skills:[],quizHistory:[],notes:'',assignments:[{id:'a1',title:'Build your event study plan',event:'Nursing Assisting',type:'Reflection',due:'2026-10-22',instructions:'Review the official event guidelines. Write down the sections you need to prepare and one goal for this week.',school:'westbridge',submitted:false},{id:'a2',title:'Review the official skill rubric',event:'Nursing Assisting',type:'Skill checklist',due:'2026-10-24',instructions:'Open your event guidelines and review the skill rating sheets with your advisor. Reflect on what you want to practice next.',school:'westbridge',submitted:false}],posts:[{id:'p1',school:'westbridge',author:'Ms. Rivera',role:'Instructor',text:'Skills lab is Thursday at 3:30 in room 204. Bring your event guidelines and a question you want to work through.',date:'2026-10-18T14:00:00Z'},{id:'p2',school:'westbridge',author:'Jordan Lee',role:'Student',text:'Anyone up for a terminology study session after school? I’m putting together a set of word roots.',date:'2026-10-18T13:00:00Z'}]}; }
export function selectEvent(state,name) { if(!EVENTS.some(e=>e.name===name))throw new Error('Choose an event from the secondary catalog.');if(state.event&&state.event!==name)throw new Error('Your annual event is already selected. Ask your instructor to change it.');return {...state,event:name}; }
export function completeLesson(state,id) { return state.completed.includes(id)?state:{...state,completed:[...state.completed,id]}; }
export function createAssignment(state,data) { const title=String(data.title||'').trim();if(!title)throw new Error('Add an assignment title.');if(!EVENTS.some(e=>e.name===data.event))throw new Error('Choose a valid event.');if(!/^\d{4}-\d{2}-\d{2}$/.test(data.due||''))throw new Error('Choose a due date.');return {...state,assignments:[{...data,title,id:crypto.randomUUID(),school:state.school,submitted:false},...state.assignments]}; }
export function assignmentsFor(state,role='student') { return state.assignments.filter(a=>a.school===state.school&&(role==='teacher'||a.event===state.event)); }
export function postsFor(state) { return state.posts.filter(p=>p.school===state.school); }
export function addPost(state,text) { const clean=String(text||'').trim();if(!clean)throw new Error('Write a message first.');if(clean.length>1500)throw new Error('Keep your message under 1,500 characters.');return {...state,posts:[{id:crypto.randomUUID(),school:state.school,author:state.role==='teacher'?'Ms. Rivera':'Maya Chen',role:state.role==='teacher'?'Instructor':'Student',text:clean,date:new Date().toISOString()},...state.posts]}; }
export const LESSONS = [{id:'guidelines',title:'Get to know your event',time:'5 min',tag:'Start here',body:'A good plan starts with the current event guidelines. They describe who can compete, what each round includes, the official references, and how work is evaluated. Use the link below to find your event, then save the current year’s document.',question:'What should you use as the source of truth for your event?',options:['A previous competitor’s notes','The current official event guidelines','A general online study guide'],answer:1,explanation:'The current official guidelines set the requirements. Notes and study tools can support them, but should not replace them.'},{id:'plan',title:'Make a plan you can keep',time:'4 min',tag:'Study habits',body:'Break the requirements in your event guide into small preparation sessions. Make room for both learning and recall. If your event has a performance, skill, or presentation component, schedule time to practice it with feedback from your advisor.',question:'Which plan gives you a clearer next step?',options:['Study everything tonight','Review one topic, then recall it without notes','Wait until competition week'],answer:1,explanation:'A specific, manageable task makes it easier to begin and check what you have learned.'},{id:'reflect',title:'Turn feedback into progress',time:'3 min',tag:'Reflection',body:'After practice, write down what went well, what needs attention, and one change to try next time. Keep practice notes separate from official requirements, and ask your instructor about anything that is unclear.',question:'What is the most useful follow-up to practice?',options:['Record one improvement to try next time','Ignore the feedback','Only compare your score to others'],answer:0,explanation:'A concrete next action turns feedback into another opportunity to learn.'}];
export function progress(state) {return Math.round(state.completed.length/LESSONS.length*100);}
